from pathlib import Path
import base64

ROOT = Path.cwd()
panel_path = ROOT / "app/(portal)/game/components/HouseOfChancesPanel.tsx"
action_path = ROOT / "app/(portal)/game/house-of-chances-actions.ts"
access_path = ROOT / "lib/auth/admin-section-access.ts"
layout_path = ROOT / "app/(portal)/admin/layout.tsx"
admin_actions_path = ROOT / "app/(portal)/admin/house-of-chances/actions.ts"
admin_page_path = ROOT / "app/(portal)/admin/house-of-chances/page.tsx"

for path in [panel_path, action_path, access_path, layout_path]:
    if not path.exists():
        raise SystemExit(f"Missing expected file: {path}")

panel = panel_path.read_text(encoding="utf-8")
panel = panel.replace('"border border-[rgb(var(--sep-colour-8b673f))]/70",', '"border border-[rgb(var(--sep-colour-987344))]",', 1)
panel = panel.replace('<div className="pointer-events-none absolute inset-[3px] border border-[rgb(var(--sep-colour-b58a4c))]/25" />', '<div className="pointer-events-none absolute inset-[3px] border border-[rgb(var(--sep-colour-987344))]/35" />', 1)
panel = panel.replace('{result.matched_rule_name ?? "No Prize"}', '{result.matched_rule_name ?? "No winnings this time"}', 1)

old = '''              {result.reward_snapshot.length ? (
                <div className="mt-2 flex flex-wrap justify-center gap-2">
                  {result.reward_snapshot.map((reward, index) => (
                    <span
                      key={`${reward.type}-${index}`}
                      className="border border-[rgb(var(--sep-colour-765735))]/55 bg-[rgb(var(--sep-colour-21170f))] px-2 py-1 text-[8px] text-[rgb(var(--sep-colour-d8bb8a))]"
                    >
                      {rewardLabel(reward)}
                    </span>
                  ))}
                </div>
              ) : (
                <p className="mt-2 text-[9px] text-[rgb(var(--sep-colour-756958))]">
                  No winnings this time.
                </p>
              )}'''
new = '''              {result.reward_snapshot.length ? (
                <div className="mt-2 flex flex-wrap justify-center gap-2">
                  {result.reward_snapshot.map((reward, index) => (
                    <span
                      key={`${reward.type}-${index}`}
                      className="border border-[rgb(var(--sep-colour-765735))]/55 bg-[rgb(var(--sep-colour-21170f))] px-2 py-1 text-[8px] text-[rgb(var(--sep-colour-d8bb8a))]"
                    >
                      {rewardLabel(reward)}
                    </span>
                  ))}
                </div>
              ) : null}'''
if old in panel:
    panel = panel.replace(old, new, 1)

old = '''          {message ? (
            <p
              aria-live="polite"
              className={[
                "mt-3 text-center text-[9px]",
                result
                  ? "text-[rgb(var(--sep-colour-c3a778))]"
                  : "text-red-400",
              ].join(" ")}
            >
              {message}
            </p>
          ) : null}'''
new = '''          {message && !result ? (
            <p
              aria-live="polite"
              className="mt-3 text-center text-[9px] text-red-400"
            >
              {message}
            </p>
          ) : null}'''
if old in panel:
    panel = panel.replace(old, new, 1)
panel_path.write_text(panel, encoding="utf-8")

server_action = action_path.read_text(encoding="utf-8")
server_action = server_action.replace('      : "No prize this time.",', '      : null,', 1)
action_path.write_text(server_action, encoding="utf-8")

access = access_path.read_text(encoding="utf-8")
if '  | "house_of_chances"' not in access:
    access = access.replace('  | "world";', '  | "house_of_chances"\\n  | "world";', 1)
if '  house_of_chances: ["owner", "admin"],' not in access:
    access = access.replace('  world: ["owner", "admin", "master"],', '  house_of_chances: ["owner", "admin"],\\n  world: ["owner", "admin", "master"],', 1)
access_path.write_text(access, encoding="utf-8")

layout = layout_path.read_text(encoding="utf-8")
if '/admin/house-of-chances' not in layout:
    anchor = '''            {can("items") ? (
              <AdminNavigationLink href="/admin/items">
                Items
              </AdminNavigationLink>
            ) : null}'''
    insert = anchor + '''

            {can("house_of_chances") ? (
              <AdminNavigationLink href="/admin/house-of-chances">
                House of Chances
              </AdminNavigationLink>
            ) : null}'''
    if anchor not in layout:
        raise SystemExit("Could not find admin nav anchor.")
    layout = layout.replace(anchor, insert, 1)
layout_path.write_text(layout, encoding="utf-8")

admin_actions_path.parent.mkdir(parents=True, exist_ok=True)
admin_actions_path.write_bytes(base64.b64decode(''))
admin_page_path.write_bytes(base64.b64decode(''))

print("SUCCESS")
print("House of Chances admin phase applied.")
print("Now run: npm run build")